package com.nivor.habit;
import com.nivor.common.entity.AuditedEntity;import com.nivor.user.User;import jakarta.persistence.*;import java.time.LocalTime;
@Entity@Table(name="habits",indexes=@Index(name="idx_habit_user",columnList="user_id"))public class Habit extends AuditedEntity{
 @ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id",nullable=false)private User user;@Column(nullable=false,length=120)private String name;@Column(length=2000)private String description;@Enumerated(EnumType.STRING)@Column(nullable=false,length=16)private HabitFrequency frequency=HabitFrequency.DAILY;@Column(nullable=false)private int targetCount=1;private LocalTime reminderTime;@Column(length=40)private String color;@Column(nullable=false)private boolean active=true;
 protected Habit(){}public User getUser(){return user;}public void setUser(User v){user=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public HabitFrequency getFrequency(){return frequency;}public void setFrequency(HabitFrequency v){frequency=v;}public int getTargetCount(){return targetCount;}public void setTargetCount(int v){targetCount=v;}public LocalTime getReminderTime(){return reminderTime;}public void setReminderTime(LocalTime v){reminderTime=v;}public String getColor(){return color;}public void setColor(String v){color=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}
}
